import { expect, test, type Page } from "@playwright/test";

// Fixtures: web/e2e/fixtures, plus big.log (over 5 MB) and Notes/latin1.txt
// (not UTF-8) generated by e2e/serve.sh.

const item = (page: Page, name: string) =>
  page.getByRole("tree").getByRole("treeitem", { name });

const editor = (page: Page) => page.locator(".cm-content");

test.beforeEach(async ({ page }) => {
  // Test mode signs in at once as the Owner and lands on the app.
  await page.goto("/auth/signin");
});

test("the sidebar shows the Root Folder with folders collapsed", async ({ page }) => {
  await expect(item(page, "Notes")).toBeVisible();
  await expect(item(page, "readme.md")).toBeVisible();
  await expect(item(page, "Notes")).toHaveAttribute("aria-expanded", "false");
  await expect(item(page, "Today.md")).toHaveCount(0);
});

test("folders expand and collapse", async ({ page }) => {
  await item(page, "Notes").click();
  await expect(item(page, "Notes")).toHaveAttribute("aria-expanded", "true");
  await expect(item(page, "Today.md")).toBeVisible();
  await expect(item(page, "Archive")).toBeVisible();
  await expect(item(page, "2020.md")).toHaveCount(0);

  await item(page, "Archive").click();
  await expect(item(page, "2020.md")).toBeVisible();

  await item(page, "Notes").click();
  await expect(item(page, "Today.md")).toHaveCount(0);
  await expect(item(page, "2020.md")).toHaveCount(0);
});

test("clicking a Text File shows its content in the editor", async ({ page }) => {
  await item(page, "Notes").click();
  await item(page, "Today.md").click();
  await expect(editor(page)).toContainText("Buy milk.");
  await expect(item(page, "Today.md")).toHaveAttribute("aria-selected", "true");

  // CRLF files arrive with LF line endings: two lines, no stray characters.
  await item(page, "readme.md").click();
  await expect(editor(page).locator(".cm-line")).toHaveText(["Read me first.", "Second line.", ""]);
});

test("files over 5 MB are marked and don't open", async ({ page }) => {
  await item(page, "readme.md").click();
  await expect(editor(page)).toContainText("Read me first.");

  const big = item(page, "big.log");
  await expect(big).toContainText("too large");
  await expect(big).toHaveAttribute("aria-disabled", "true");
  await big.click({ force: true });
  await expect(editor(page)).toContainText("Read me first.");
});

test("a file found to be binary on open is marked binary for the session", async ({ page }) => {
  await item(page, "readme.md").click();
  await item(page, "Notes").click();
  const latin1 = item(page, "latin1.txt");
  await expect(latin1).not.toHaveAttribute("aria-disabled", "true");

  await latin1.click();
  await expect(latin1).toContainText("binary");
  await expect(latin1).toHaveAttribute("aria-disabled", "true");
  await expect(editor(page)).toContainText("Read me first.");

  // Still marked after collapsing and re-expanding its folder.
  await item(page, "Notes").click();
  await item(page, "Notes").click();
  await expect(item(page, "latin1.txt")).toContainText("binary");
});
